                if r < min_r_shape:
                    min_r_shape = r
                if r > max_r_shape:
                    max_r_shape = r
                if c < min_c_shape:
                    min_c_shape = c
                if c > max_c_shape:
                    max_c_shape = c

    # Sizes
    border_h = max_r_border - min_r_border + 1
    border_w = max_c_border - min_c_border + 1
    interior_h = border_h - 2
    interior_w = border_w - 2

    shape_h = max_r_shape - min_r_shape + 1
    shape_w = max_c_shape - min_c_shape + 1

    # Scaling factor (integer)
    scale = interior_h // shape_h   # same as interior_w // shape_w

    # Extract shape pattern (including zeros inside its bounding box)
    shape_grid = [[0] * shape_w for _ in range(shape_h)]
    for i in range(shape_h):
        for j in range(shape_w):
            shape_grid[i][j] = grid[min_r_shape + i][min_c_shape + j]

    # Create output grid (border size)
    out_h = border_h
    out_w = border_w
    out = [[0] * out_w for _ in range(out_h)]

    # Draw border
    for i in range(out_h):
        for j in range(out_w):
            if i == 0 or i == out_h - 1 or j == 0 or j == out_w - 1:
                out[i][j] = border_color

    # Fill interior with scaled shape
    for r in range(interior_h):
        for c in range(interior_w):
            sr = r // scale
            sc = c // scale
            val = shape_grid[sr][sc]
            if val != 0:
                out[r + 1][c + 1] = val

    return out

